insert into public.design_styles (id, project_id, name, name_ar, materials, materials_ar, mood, mood_ar, palette, palettes, palette_note, palette_note_ar, images) values
  ('nk-modern-minimal', 'nk-noor-khuzam', 'Modern Minimal', 'مودرن مينيمال', array['Light oak','Warm cream & greige','Soft upholstery','Pale stone','Minimal metal details']::text[], array['بلوط فاتح','كريمي دافئ وبيج رمادي','مفروشات ناعمة','حجر فاتح','تفاصيل معدنية بسيطة']::text[], 'Flat ceilings with illuminated shadow gaps, warm cream and greige, natural oak and restrained dark accents. Light wood, soft upholstery, pale stone surfaces and minimal metal details.', 'أسقف مستوية بفراغات ظلّ مضيئة، كريمي دافئ وبيج رمادي، خشب البلوط الطبيعي ولمسات داكنة محدودة. خشب فاتح ومفروشات ناعمة وأسطح حجرية فاتحة وتفاصيل معدنية بسيطة.', array['#F3EEE6','#CFC5B8','#B08A5A','#2A2724']::text[], '[{"id":"nk-mm-oak","name":"Cream & Oak","nameAr":"كريمي وبلوط","colors":["#F3EEE6","#CFC5B8","#B08A5A","#2A2724"]},{"id":"nk-mm-sage","name":"Sage & Linen","nameAr":"مريمي وكتّان","colors":["#F1EFE8","#B9C2B1","#8A9A85","#3B3F39"]},{"id":"nk-mm-slate","name":"Slate & Sand","nameAr":"رمادي ورملي","colors":["#EFEAE2","#D6C8B2","#6E7480","#2E3138"]}]'::jsonb, 'The palette changes the accessories, cushions, rugs, bedding, wall art and soft goods — the furniture, kitchen and appliances stay the same.', 'لوحة الألوان تغيّر الإكسسوارات والمخدات والسجاد والمفارش واللوحات والمفروشات الناعمة — ويبقى الأثاث والمطبخ والأجهزة كما هي.', '[{"id":"mm-1","label":"Open kitchen, dining & living · view 1","labelAr":"المطبخ المفتوح والطعام والمعيشة · منظر ١","src":"/images/noor/mm-1.jpg"},{"id":"mm-2","label":"Open kitchen, dining & living · view 2","labelAr":"المطبخ المفتوح والطعام والمعيشة · منظر ٢","src":"/images/noor/mm-2.jpg"},{"id":"mm-3","label":"Bedroom 09 · main view","labelAr":"غرفة النوم ٠٩ · المنظر الرئيسي","src":"/images/noor/mm-3.jpg"},{"id":"mm-4","label":"Bedroom 11","labelAr":"غرفة النوم ١١","src":"/images/noor/mm-4.jpg"},{"id":"mm-5","label":"Dressing room 12","labelAr":"غرفة الملابس ١٢","src":"/images/noor/mm-5.jpg"},{"id":"mm-6","label":"Bedroom 07","labelAr":"غرفة النوم ٠٧","src":"/images/noor/mm-6.jpg"},{"id":"mm-7","label":"Bathroom 08","labelAr":"الحمّام ٠٨","src":"/images/noor/mm-7.jpg"}]'::jsonb),
  ('nk-new-classic', 'nk-noor-khuzam', 'New Classic', 'كلاسيكي جديد', array['Panelled walls','Natural oak','Warm cream & greige','Soft upholstery','Pale stone']::text[], array['جدران بألواح زخرفية','بلوط طبيعي','كريمي دافئ وبيج رمادي','مفروشات ناعمة','حجر فاتح']::text[], 'Classic proportions with a contemporary hand: panelled walls, warm cream and greige, natural oak, soft upholstery and pale stone with restrained dark accents.', 'نِسَب كلاسيكية بلمسة معاصرة: جدران بألواح زخرفية، كريمي دافئ وبيج رمادي، بلوط طبيعي، مفروشات ناعمة وحجر فاتح مع لمسات داكنة محدودة.', array['#EFE8DC','#D5C7B4','#9C7B55','#3A322B']::text[], '[{"id":"nk-nc-stone","name":"Stone & Walnut","nameAr":"حجري وجوزي","colors":["#EFE8DC","#D5C7B4","#9C7B55","#3A322B"]},{"id":"nk-nc-ivory","name":"Ivory & Brass","nameAr":"عاجي ونحاسي","colors":["#F4EFE4","#DDD3C2","#B99A5B","#4A423A"]},{"id":"nk-nc-navy","name":"Navy & Camel","nameAr":"كحلي وجملي","colors":["#EDE7DC","#C9A97A","#2B3A55","#1F2633"]}]'::jsonb, 'The palette changes the accessories, cushions, rugs, bedding, wall art and soft goods — the furniture, kitchen and appliances stay the same.', 'لوحة الألوان تغيّر الإكسسوارات والمخدات والسجاد والمفارش واللوحات والمفروشات الناعمة — ويبقى الأثاث والمطبخ والأجهزة كما هي.', '[{"id":"nc-1","label":"Open kitchen, dining & living · view 1","labelAr":"المطبخ المفتوح والطعام والمعيشة · منظر ١","src":"/images/noor/nc-1.jpg"},{"id":"nc-2","label":"Open kitchen, dining & living · view 2","labelAr":"المطبخ المفتوح والطعام والمعيشة · منظر ٢","src":"/images/noor/nc-2.jpg"},{"id":"nc-3","label":"Bedroom 11","labelAr":"غرفة النوم ١١","src":"/images/noor/nc-3.jpg"},{"id":"nc-4","label":"Bathroom 08","labelAr":"الحمّام ٠٨","src":"/images/noor/nc-4.jpg"},{"id":"nc-5","label":"Dressing room 12","labelAr":"غرفة الملابس ١٢","src":"/images/noor/nc-5.jpg"},{"id":"nc-6","label":"Bedroom 09 · main view","labelAr":"غرفة النوم ٠٩ · المنظر الرئيسي","src":"/images/noor/nc-6.jpg"},{"id":"nc-7","label":"Bedroom 07","labelAr":"غرفة النوم ٠٧","src":"/images/noor/nc-7.jpg"}]'::jsonb),
  ('nk-warm-contemporary', 'nk-noor-khuzam', 'Warm Contemporary', 'معاصر دافئ', array['Dark wood','Olive green','Terracotta','Soft upholstery','Pale stone']::text[], array['خشب داكن','أخضر زيتوني','تيراكوتا','مفروشات ناعمة','حجر فاتح']::text[], 'Warm contemporary style with earthy tones: olive green, terracotta and natural wood. Dark wood, soft upholstery, pale stone surfaces and minimal metal details.', 'طابع معاصر دافئ بألوان ترابية: أخضر زيتوني وتيراكوتا وخشب طبيعي. خشب داكن ومفروشات ناعمة وأسطح حجرية فاتحة وتفاصيل معدنية بسيطة.', array['#EFE6D8','#5F6B4A','#B5643C','#6B4A33']::text[], '[{"id":"nk-wc-olive","name":"Olive & Terracotta","nameAr":"زيتوني وتيراكوتا","colors":["#EFE6D8","#5F6B4A","#B5643C","#6B4A33"]},{"id":"nk-wc-rust","name":"Rust & Clay","nameAr":"صدئي وطيني","colors":["#F0E4D6","#C9A27E","#A3512F","#4E3327"]},{"id":"nk-wc-forest","name":"Forest & Sand","nameAr":"غابي ورملي","colors":["#EEE7DA","#D8C7A8","#3E5A46","#2B3A2F"]}]'::jsonb, 'The palette changes the accessories, cushions, rugs, bedding, wall art and soft goods — the furniture, kitchen and appliances stay the same.', 'لوحة الألوان تغيّر الإكسسوارات والمخدات والسجاد والمفارش واللوحات والمفروشات الناعمة — ويبقى الأثاث والمطبخ والأجهزة كما هي.', '[{"id":"wc-1","label":"Open kitchen, dining & living · view 1","labelAr":"المطبخ المفتوح والطعام والمعيشة · منظر ١","src":"/images/noor/wc-1.jpg"},{"id":"wc-2","label":"Open kitchen, dining & living · view 2","labelAr":"المطبخ المفتوح والطعام والمعيشة · منظر ٢","src":"/images/noor/wc-2.jpg"},{"id":"wc-3","label":"Bedroom 11","labelAr":"غرفة النوم ١١","src":"/images/noor/wc-3.jpg"},{"id":"wc-4","label":"Bathroom 08","labelAr":"الحمّام ٠٨","src":"/images/noor/wc-4.jpg"},{"id":"wc-5","label":"Dressing room 12","labelAr":"غرفة الملابس ١٢","src":"/images/noor/wc-5.jpg"},{"id":"wc-6","label":"Bedroom 09 · main view","labelAr":"غرفة النوم ٠٩ · المنظر الرئيسي","src":"/images/noor/wc-6.jpg"},{"id":"wc-7","label":"Bedroom 07","labelAr":"غرفة النوم ٠٧","src":"/images/noor/wc-7.jpg"}]'::jsonb)
