  ('nk-pkg-modern-minimal', 'nk-noor-khuzam', 'nk-modern-minimal', 'Modern Minimal', 'مودرن مينيمال', 'Theme 01', 'ثيم ٠١', 'Complete move-in kit in the Modern Minimal theme — furniture, soft goods, appliances, kitchen, bathroom, smart essentials, delivery and installation. Itemised per unit type in Appendix F-1.', 'حزمة انتقال كاملة بثيم مودرن مينيمال — أثاث ومفروشات وأجهزة ومطبخ وحمّام وأساسيات المنزل الذكي مع التوصيل والتركيب. مفصّلة لكل نوع وحدة في الملحق F-1.', 92, 3, true, '{"NK-S":42000,"NK-M":53000,"NK-L":63000,"NK-TH":77500,"NK-PH":77500}'::jsonb, '[{"room":"Master Bedroom","roomAr":"غرفة النوم الرئيسية","item":"Bed frame 160×200 (queen/king)","itemAr":"سرير رئيسي بهيكل خشبي","notes":"Solid wood","qty":1,"supplier":"Revnu"},{"room":"Master Bedroom","roomAr":"غرفة النوم الرئيسية","item":"Mattress","itemAr":"مرتبة","notes":"Medium-firm foam/spring","qty":1,"supplier":"Revnu"},{"room":"Master Bedroom","roomAr":"غرفة النوم الرئيسية","item":"Wardrobe · 3-door","itemAr":"دولاب ملابس","notes":"220cm H × 150cm W, with mirror","qty":2,"supplier":"Revnu"},{"room":"Master Bedroom","roomAr":"غرفة النوم الرئيسية","item":"Bedside tables (pair)","itemAr":"كومودينو (زوج)","notes":"Matching set, 2 drawers each","qty":2,"supplier":"Revnu"},{"room":"Master Bedroom","roomAr":"غرفة النوم الرئيسية","item":"Chest of drawers · 4-drawer","itemAr":"خزانة أدراج","notes":"Matching bedroom set","qty":1,"supplier":"Revnu"},{"room":"Master Bedroom","roomAr":"غرفة النوم الرئيسية","item":"Curtains + blackout lining","itemAr":"ستائر مع بطانة معتمة","notes":"Floor-to-ceiling, 2 panels per window","qty":4,"supplier":"Revnu"},{"room":"Master Bedroom","roomAr":"غرفة النوم الرئيسية","item":"Bedding set","itemAr":"طقم مفارش","notes":"Hotel quality, 400-thread count","qty":1,"supplier":"Revnu"},{"room":"Master Bedroom","roomAr":"غرفة النوم الرئيسية","item":"Bedside lamps (pair)","itemAr":"مصابيح جانبية (زوج)","notes":"LED","qty":2,"supplier":"Revnu"},{"room":"Master Bedroom","roomAr":"غرفة النوم ا