insert into public.smart_home (id, project_id, name, name_ar, price, level, summary, summary_ar, includes, includes_ar) values
  ('nk-smart-basic', 'nk-noor-khuzam', 'Basic', 'الأساسية', 5000, 1, 'Entry smart layer — secure access and connected climate.', 'طبقة ذكية أساسية — دخول آمن وتكييف متصل.', array['Smart door lock — fingerprint, PIN and card','Smart thermostat for the central A/C','Dual-band Wi-Fi router','Smart-home app · shared access for guests']::text[], array['قفل ذكي — بصمة ورمز وبطاقة','ثرموستات ذكي للتكييف المركزي','راوتر واي فاي ثنائي النطاق','تطبيق المنزل الذكي · وصول مشترك للضيوف']::text[]),
  ('nk-smart-plus', 'nk-noor-khuzam', 'Plus', 'المتوسطة', 9500, 2, 'Everything in Basic plus lighting scenes, curtains and leak protection.', 'كل ما في الأساسية مع مشاهد الإضاءة والستائر والحماية من التسرّب.', array['Everything in Basic','Smart lighting · dimmable scenes in living and bedrooms','Motorised curtains · living room','Water-leak sensors · kitchen and bathrooms','Smart plugs · 4','Voice assistant · 1']::text[], array['كل ما في الأساسية','إضاءة ذكية · مشاهد قابلة للتعتيم في المعيشة وغرف النوم','ستائر كهربائية · غرفة المعيشة','حسّاسات تسرّب المياه · المطبخ والحمّامات','مقابس ذكية · ٤','مساعد صوتي · ١']::text[]),
  ('nk-smart-premium', 'nk-noor-khuzam', 'Premium', 'العالية', 15000, 3, 'Whole-home automation — security, energy and comfort, ready for remote hosting.', 'أتمتة كاملة للمنزل — أمان وطاقة وراحة، مهيّأة للتشغيل عن بُعد.', array['Everything in Plus','Video doorbell + indoor camera','Smart curtains · all bedrooms','Smart irrigation / balcony lighting','Energy monitor · main panel','Multi-room audio · 2 zones','Remote host dashboard · check-in codes per booking']::text[], array['كل ما في المتوسطة','جرس باب بكاميرا + كاميرا داخلية','ستائر ذكية · كل غرف النوم','ري ذكي / إضاءة الشرفة','مراقب استهلاك الطاقة · اللوحة الرئيسية','صوت متعدد الغرف · منطقتان','لوحة تحكم للمضيف عن بُعد · رمز دخول لكل حجز']::text[])
insert into public.ops_models (id, project_id, name, name_ar, kind, mgmt_fee, target_roi, occ_low, occ_high, summary, summary_ar, default_rate, assume) values
  ('nk-daily', 'nk-noor-khuzam', 'Daily / short-stay', 'يومي / إقامة قصيرة', 'daily', 20, 12, 58, 78, 'Nightly rental, fully managed. Priced to a 12% net annual return on the unit price at our occupancy assumption. Indicative — confirmed by the operator before contracting.', 'إيجار ليلي بإدارة كاملة. مُسعَّر ليحقق عائدًا صافيًا سنويًا 12% على سعر الوحدة وفق افتراض الإشغال لدينا. استرشادي — يؤكده المشغّل قبل التعاقد.', '{"NK-L":925,"NK-M":490,"NK-S":305,"NK-PH":1535,"NK-TH":1120}'::jsonb, '{"NK-L":{"occ":64,"risk":"high"},"NK-M":{"occ":70,"risk":"medium"},"NK-S":{"occ":74,"risk":"medium"},"NK-PH":{"occ":58,"risk":"high"},"NK-TH":{"occ":58,"risk":"high"}}'::jsonb),
  ('nk-monthly', 'nk-noor-khuzam', 'Monthly rental', 'إيجار شهري', 'monthly', 10, 10, 85, 96, '30+ day stays. Priced to a 10% net annual return on the unit price. Steady cashflow, smaller swings. Indicative — confirmed by the operator before contracting.', 'إقامات ٣٠ يومًا فأكثر. مُسعَّر ليحقق عائدًا صافيًا سنويًا 10% على سعر الوحدة. تدفّق نقدي ثابت وتذبذب أقل. استرشادي — يؤكده المشغّل قبل التعاقد.', '{"NK-L":14950,"NK-M":8500,"NK-S":5550,"NK-PH":23600,"NK-TH":17050}'::jsonb, '{"NK-L":{"occ":89,"risk":"medium"},"NK-M":{"occ":91,"risk":"low"},"NK-S":{"occ":92,"risk":"low"},"NK-PH":{"occ":85,"risk":"medium"},"NK-TH":{"occ":86,"risk":"medium"}}'::jsonb),
  ('nk-yearly', 'nk-noor-khuzam', 'Long lease (12 months+)', 'إيجار طويل (١٢ شهرًا+)', 'monthly', 6, 8, 95, 100, 'Single tenant, 12-month minimum. Priced to an 8% net annual return on the unit price. Lowest fee. Indicative — confirmed by the operator before contracting.', 'مستأجر واحد، ١٢ شهرًا كحد أدنى. مُسعَّر ليحقق عائدًا صافيًا سنويًا 8% على سعر الوحدة. أقل رسوم. استرشادي — يؤكده المشغّل قبل التعاقد.', '{"NK-L":10500,"NK-M":6050,"NK-S":4000,"NK-PH":16200,"NK-TH":11700}'::jsonb, '{"NK-L":{"occ":97,"risk":"low"},"NK-M":{"occ":98,"risk":"low"},"NK-S":{"occ":98,"risk":"low"},"NK-PH":{"occ":95,"risk":"low"},"NK-TH":{"occ":96,"risk":"low"}}'::jsonb)
